original_methods={n.name:ast.dump(n,include_attributes=False) for n in original_model.body if isinstance(n,ast.FunctionDef)}
for v in proposal['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['role'] in ('candidate','control')
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 source=(root/v['file']).read_text();tree=ast.parse(source);compile(source,v['file'],'exec')
