 assert config==v['config']
 assert hashlib.sha256(source.encode()).hexdigest() in v['note']
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:ast.dump(n,include_attributes=False) for n in model.body if isinstance(n,ast.FunctionDef)}
 assert set(methods)-set(original_methods)=={'_history_stratified_summary_values'}
